import sys
from pyro_server import PyroServer


default_port = 9092
default_inactivity_timeout = 2 * 24 * 3600


def find_ip():
    import socket
    with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as temp_socket:
        temp_socket.connect(("8.8.8.8", 80))
        ip = temp_socket.getsockname()[0]
    return ip


serv = PyroServer()
if __name__ != '__main__':
    raise RuntimeError("This launcher should be executed as __main__!")
if len(sys.argv) > 3:
    raise RuntimeError(f"Only 2 arguments can be passed to the launcher: host and port. Passed arguments: "
                       f"{sys.argv[1:]}")
if len(sys.argv) == 1:
    host = find_ip()
    port = default_port
elif len(sys.argv) == 2:
    host, port = sys.argv[1], default_port
else:
    host, port = sys.argv[1], int(sys.argv[2])

serv.launch(host, port, default_inactivity_timeout)
